idle.entry:
[Node: assign({
            callbackRef: ({ spawn }) =>
              spawn(
                fromCallback<{ type: 'START' }>(({ sendBack, receive }) => {
                  receive((event) => {
                    if (event.type === 'START') {
                      setTimeout(() => {
                        sendBack({ type: 'SEND_BACK' });
                      }, 10);
                    }
                  });
                })
              )
          })]
